#!/usr/bin/env node
const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/refs.jsonl';

const D3='http://json-schema.org/draft-03/schema#';
const D4='http://json-schema.org/draft-04/schema#';
const D6='http://json-schema.org/draft-06/schema#';
const D7='http://json-schema.org/draft-07/schema#';
const D19='https://json-schema.org/draft/2019-09/schema';
const D20='https://json-schema.org/draft/2020-12/schema';
const ALL=[D3,D4,D6,D7,D19,D20];
const M=[D7,D19,D20];
const pairs=[]; const labels=[];
function add(a,b,l){pairs.push([JSON.stringify(a),JSON.stringify(b)]);labels.push(l||'');}
function addRaw(as,bs,l){pairs.push([as,bs]);labels.push(l||'');}
function sweep(a,b,drafts=ALL,l){for(const s of drafts)add(a,Object.assign({$schema:s},b),(l||'')+' ['+s.slice(-20)+']');}

// ===== A. pointer escaping order / percent-encoding edges =====
add('x',{$defs:{'~1':{type:'integer'}},$ref:'#/$defs/%7E1'},'pct-tilde %7E1 -> key ~1 or /?');
add('x',{$defs:{'/':{type:'integer'}},$ref:'#/$defs/%7E1'},'%7E1 -> "/" key?');
add('x',{$defs:{'a/b':{type:'integer'}},$ref:'#/$defs/a%2Fb'},'%2F uppercase -> slash split?');
add('x',{$defs:{a:{b:{type:'integer'}}},$ref:'#/$defs/a%2Fb'},'%2F acts as separator?');
add('x',{$defs:{a:{b:{type:'integer'}}},$ref:'#/$defs/a%2fb'},'%2f lowercase separator?');
add('x',{$defs:{'a~1b':{type:'integer'}},$ref:'#/$defs/a~01b'},'~01 -> a~1b');
add('x',{$defs:{'a~/b':{type:'integer'}},$ref:'#/$defs/a~0~1b'},'~0~1');
add('x',{$defs:{'é':{type:'integer'}},$ref:'#/$defs/é'},'literal non-ascii key');
add('x',{$defs:{'é':{type:'integer'}},$ref:'#/$defs/%C3%A9'},'utf8 pct non-ascii');
add('x',{$defs:{'😀':{type:'integer'}},$ref:'#/$defs/😀'},'literal astral key');
add('x',{$defs:{'😀':{type:'integer'}},$ref:'#/$defs/%F0%9F%98%80'},'utf8 pct astral');
add('x',{$defs:{'a\tb':{type:'integer'}},$ref:'#/$defs/a\tb'},'literal tab in pointer');
add('x',{$defs:{'a\nb':{type:'integer'}},$ref:'#/$defs/a%0Ab'},'pct newline');
add('x',{$defs:{'a%2Fb':{type:'integer'}},$ref:'#/$defs/a%252Fb'},'double-encoded slash');
add('x',{$defs:{'a?b':{type:'integer'}},$ref:'#/$defs/a?b'},'literal query char in fragment');
add('x',{$defs:{'a#b':{type:'integer'}},$ref:'#/$defs/a#b'},'literal second # in ref');
add('x',{$defs:{'a b':{type:'integer'}},$ref:'#/$defs/a%2520b'},'%2520');
add('x',{$defs:{'A':{type:'integer'}},$ref:'#/$defs/a'},'pointer case sensitivity');
add('x',{$defs:{a:{type:'integer'}},$ref:'#/$DEFS/a'},'pointer case sensitivity 2');
add('x',{$defs:{a:{type:'integer'}},$ref:'/$defs/a'},'ref without leading #');
add('x',{$defs:{a:{type:'integer'}},$ref:'#$defs/a'},'ref #$defs/a (anchor-ish)');
add('x',{$defs:{a:{type:'integer'}},$ref:'##/$defs/a'},'double hash');
add('x',{$defs:{a:{type:'integer'}},$ref:'#/$defs/a/'},'trailing slash -> key ""');
add('x',{$defs:{a:{'':{type:'integer'}}},$ref:'#/$defs/a/'},'trailing slash w/ empty key present');

// ===== B. pointer through arrays in schema slots (per-draft crash matrix) =====
sweep('x',{definitions:{a:[{type:'integer'}]},$ref:'#/definitions/a/0'},ALL,'definitions list walk');
sweep('x',{$defs:{a:[{type:'integer'}]},$ref:'#/$defs/a/0'},ALL,'$defs list walk');
sweep('x',{properties:{p:[{type:'integer'}]},$ref:'#/properties/p/0'},ALL,'properties list walk');
sweep('x',{items:[{type:'integer'}],$ref:'#/items/0'},ALL,'items list walk');
sweep('x',{prefixItems:[{type:'integer'}],$ref:'#/prefixItems/0'},ALL,'prefixItems list walk');
sweep('x',{allOf:[{type:'integer'}],$ref:'#/allOf/0'},ALL,'allOf list walk');
sweep('x',{dependencies:{q:[{type:'integer'}]},$ref:'#/dependencies/q/0'},ALL,'dependencies list walk');
sweep('x',{patternProperties:{'^p':[{type:'integer'}]},$ref:'#/patternProperties/%5Ep/0'},ALL,'patternProperties list walk');
sweep('x',{contains:[{type:'integer'}],$ref:'#/contains/0'},ALL,'contains list walk');
sweep('x',{additionalProperties:[{type:'integer'}],$ref:'#/additionalProperties/0'},ALL,'addlProps list walk');
sweep('x',{not:[{type:'integer'}],$ref:'#/not/0'},ALL,'not list walk');
sweep('x',{$defs:{a:{items:[{type:'integer'}]}},$ref:'#/$defs/a/items/0'},ALL,'nested items list walk');
add('x',{items:[{type:'integer'}],$ref:'#/items'},'ref to the list itself (2020-12)');
add('x',{anyOf:[{type:'integer'}],$ref:'#/anyOf/-'},'pointer index "-"');
