  add({x:1,y:2},{$schema:s,$defs:{a:{properties:{x:true}}},unevaluatedProperties:false},'unevalProps no ref baseline');
  add([1,2],{$schema:s,allOf:[{$ref:'#/$defs/a'}],$defs:{a:{prefixItems:[{type:'integer'}]}},unevaluatedItems:false},'unevalItems via ref');
}
// ===== D. $ref inside contains / dependencies / dependentRequired etc =====
sweep([1,2],{contains:{$ref:'#/$defs/a'},$defs:{a:{type:'string'}}},[D6,D7,D19,D20],'contains ref');
sweep({p:1,q:2},{dependencies:{p:{$ref:'#/$defs/a'}},$defs:{a:{type:'string'}}},[D4,D6,D7,D19,D20],'dependencies ref');
sweep({p:1},{if:{$ref:'#/$defs/t'},then:{$ref:'#/$defs/a'},else:{$ref:'#/$defs/a'},$defs:{t:{type:'object'},a:{type:'string'}}},M,'if/then ref counting');
sweep(['a','b'],{items:[{$ref:'#/$defs/a'},{$ref:'#/$defs/a'}],$defs:{a:{type:'integer'}}},[D4,D6,D7,D19],'items array of refs');
sweep(['a','b'],{prefixItems:[{$ref:'#/$defs/a'},{$ref:'#/$defs/a'}],$defs:{a:{type:'integer'}}},[D20],'prefixItems refs');

// ===== E. $schema inside a subresource (dialect switch) =====
add({p:[1,'x']},{$schema:D7,definitions:{a:{$id:'http://x/a',$schema:D20,prefixItems:[{type:'string'}]}},properties:{p:{$ref:'http://x/a'}}},'subresource $schema 2020 inside draft7');
add({p:[1,'x']},{$schema:D20,$defs:{a:{$id:'http://x/a',$schema:D7,items:[{type:'string'}]}},properties:{p:{$ref:'http://x/a'}}},'subresource $schema d7 inside 2020');
add('x',{$schema:D7,definitions:{a:{$id:'http://x/a',$schema:D20,$defs:{b:{type:'integer'}},$ref:'#/$defs/b',minLength:99}},properties:{}, allOf:[{$ref:'http://x/a'}]},'sibling rule follows subresource dialect?');
add('x',{$schema:D20,$defs:{a:{$id:'http://x/a',$schema:D7,definitions:{b:{type:'integer'}},$ref:'#/definitions/b',minLength:99}},allOf:[{$ref:'http://x/a'}]},'d7 subresource sibling suppression');
add('x',{definitions:{a:{$schema:D7,type:'integer'}},$ref:'#/definitions/a'},'$schema in subschema w/o $id');

// ===== F. $vocabulary =====
add('x',{$schema:D20,$vocabulary:{'https://json-schema.org/draft/2020-12/vocab/core':true},type:'integer'},'$vocabulary present');
add('x',{$schema:D19,$vocabulary:{'https://json-schema.org/draft/2019-09/vocab/validation':false},type:'integer',minLength:99},'$vocabulary false validation');

// ===== G. meta-schema variants =====
const metas=[
 'https://json-schema.org/draft/2020-12/meta/applicator',
 'https://json-schema.org/draft/2020-12/meta/unevaluated',
 'https://json-schema.org/draft/2020-12/meta/format-annotation',
 'https://json-schema.org/draft/2020-12/meta/content',
 'https://json-schema.org/draft/2020-12/meta/meta-data',
 'https://json-schema.org/draft/2019-09/meta/core',
 'https://json-schema.org/draft/2019-09/meta/applicator',
 'https://json-schema.org/draft/2019-09/meta/format',
 'https://json-schema.org/draft/2019-09/meta/hyper-schema',
 'https://json-schema.org/draft/2020-12/hyper-schema',
 'http://json-schema.org/draft-07/hyper-schema#',
 'http://json-schema.org/draft/2020-12/schema',
 'https://json-schema.org/draft-07/schema#',
 'https://json-schema.org/draft-06/schema#',
 'http://json-schema.org/draft-05/schema#',
 'https://json-schema.org/schema#',
 'http://json-schema.org/draft-07/schema#/definitions/simpleTypes',
];
for(const m of metas) add('x',{$ref:m},'meta '+m);
add({},{$ref:'https://json-schema.org/draft/2020-12/meta/applicator'},'{} vs applicator meta');
