add('x',{$schema:D19,$ref:D7},'d7 meta referenced from 2019 doc');

// ===== H. $dynamicRef / $recursiveRef dynamic-scope semantics =====
const tree20={$schema:D20,$id:'http://x/tree',$dynamicAnchor:'node',type:'object',properties:{data:true,children:{type:'array',items:{$dynamicRef:'#node'}}}};
const strictTree={$schema:D20,$id:'http://x/strict',$dynamicAnchor:'node',$ref:'http://x/tree',unevaluatedProperties:false,$defs:{t:tree20}};
add({children:[{daat:1}]},Object.assign({},strictTree),'dynamic scope strict-tree (should catch typo if true dyn scope)');
