add({children:[{daat:1}]},{$schema:D20,$id:'http://x/tree2',$dynamicAnchor:'node',type:'object',properties:{children:{type:'array',items:{$dynamicRef:'#node'}}}},'plain tree no strict');
// $dynamicRef with full URI
add({p:1},{$schema:D20,$id:'http://x/r',$dynamicAnchor:'n',type:'object',properties:{p:{$dynamicRef:'http://x/r#n'}}},'dynamicRef absolute uri');
add({p:1},{$schema:D20,$defs:{a:{$anchor:'n',type:'string'}},properties:{p:{$dynamicRef:'#n'}}},'dynamicRef binds plain anchor in $defs');
add({p:1},{$schema:D20,$dynamicAnchor:'n',type:'object',properties:{p:{$ref:'#n'}}},'plain $ref to dynamicAnchor recursion?');
