add({children:[{daat:1}]},{$schema:D19,$id:'http://y/strict',$recursiveAnchor:true,$ref:'http://y/tree',unevaluatedProperties:false,$defs:{t:{$id:'http://y/tree',$recursiveAnchor:true,type:'object',properties:{children:{type:'array',items:{$recursiveRef:'#'}}}}}},'2019 recursiveRef dyn scope');
add({p:1},{$schema:D19,$recursiveAnchor:false,type:'object',properties:{p:{$recursiveRef:'#'}}},'recursiveAnchor false');
add({p:1},{$schema:D19,type:'object',properties:{p:{$recursiveRef:'#'}}},'recursiveRef no anchor');
add('x',{$schema:D20,$dynamicAnchor:'n',$dynamicRef:'#n'},'root dynamicRef self loop');
add('x',{$schema:D19,$recursiveAnchor:true,$recursiveRef:'#'},'root recursiveRef self loop');
add({p:1},{$schema:D20,$dynamicRef:'#/$defs/a',$defs:{a:{type:'string'}}},'dynamicRef with pointer fragment');

// ===== I. $id edge cases =====
add('x',{$schema:D7,$id:'http://x/',id:'http://z/',definitions:{a:{type:'integer'}},allOf:[{$ref:'http://x/#/definitions/a'}]},'both $id and id, draft7');
add('x',{$schema:D4,$id:'http://x/',id:'http://z/',definitions:{a:{type:'integer'}},allOf:[{$ref:'http://z/#/definitions/a'}]},'both, draft4 uses id');
add('x',{$id:'urn:example:root',$defs:{a:{type:'integer'}},allOf:[{$ref:'urn:example:root#/$defs/a'}]},'urn base + pointer');
add('x',{$id:'urn:example:root',$defs:{a:{$id:'urn:example:a',type:'integer'}},allOf:[{$ref:'urn:example:a'}]},'urn subresource');
add('x',{$id:'urn:example:root',$defs:{a:{$id:'sub',type:'integer'}},allOf:[{$ref:'sub'}]},'relative ref against urn base');
